insert into public.portfolio_projects (id,data,status,sort_order) values ('maison-melange-web','{"id":"maison-melange-web","slug":"maison-melange-web","title":"Maison Mélange / Digital Flagship","eyebrow":"E-COMMERCE · SHOPIFY · FOUNDER BRAND","category":"Web & products","client_type":"Founder-led","role":"Shopify storefront · Identity · Product content · E-commerce","summary":"A fully launched botanical body-care storefront bringing Maison Mélange’s aesthetic into the buying journey. Built around brand identity, collections and commerce.","approach":"A brand-first Shopify experience that connects editorial imagery, a botanical identity and product discovery.","outcome":"Shopify storefront launched.","cover":"/assets/media/maison-editorial-cover.webp","media":[{"type":"image","src":"/assets/media/maison-editorial-cover.webp","caption":"Brand and product visual language"}],"tags":["Shopify","Commerce","Launch"],"feature_rank":99,"featured":false,"status":"published","site_url":"https://maisonmelange.com","sort_order":700}'::jsonb,'published',700) on conflict(id) do nothing;
insert into public.portfolio_projects (id,data,status,sort_order) values ('silk-web','{"id":"silk-web","slug":"silk-web","title":"Silk / Experience & Systems","eyebrow":"SERVICE DESIGN · WEB · CRM WORKFLOWS","category":"Web & products","client_type":"Founder-led","role":"Brand identity · Booking experience · Operational workflows","summary":"A service and digital experience designed to make inquiries, scheduling and client follow-up feel seamless. Brand, web presence and supporting CRM/booking workflows.","approach":"Connect the front-facing experience to practical follow-through: inquiry, booking, communication, and arrival. The original portfolio documents a marketing site and an Airtable/Calendly CRM integration.","outcome":"Brand and marketing website developed; backend workflows documented in the original portfolio.","cover":"/assets/media/silk-logo.webp","media":[{"type":"image","src":"/assets/media/silk-logo.webp","caption":"Silk monogram and identity"}],"tags":["Operations","Web","CRM","Brand"],"feature_rank":99,"featured":false,"status":"published","site_url":"https://silkscheduling.com","sort_order":701}'::jsonb,'published',701) on conflict(id) do nothing;
insert into public.portfolio_projects (id,data,status,sort_order) values ('staywell-web','{"id":"staywell-web","slug":"staywell-web","title":"Staywellthy / Luxury Travel","eyebrow":"CLIENT · CUSTOM WEB BUILD · COMMERCE","category":"Web & products","client_type":"Client work","role":"Web design · Custom code · Domain setup · Booking experiences","summary":"Luxury travel client experience built around a video-led landing page, booking collections and a custom visual presentation.","approach":"An editorial digital destination designed for discovery and booking, with custom-code elements and Shopify integration documented in the original portfolio.","outcome":"Website and domain launched, as documented in the previous portfolio.","cover":"/assets/media/staywell-editorial-cover.webp","media":[{"type":"image","src":"/assets/media/staywell-editorial-cover.webp","caption":"Editorial representation of the travel brand, not a website screenshot"}],"tags":["Client","Web build","Shopify","Travel"],"feature_rank":99,"featured":false,"status":"published","site_url":"https://staywellthyluxurytravel.com","sort_order":702}'::jsonb,'published',702) on conflict(id) do nothing;
