insert into public.portfolio_settings (key,value) values ('about','"Multidisciplinary brand designer and creative director based in Philadelphia. I work across brand identity, full-stack web development, 3D design, campaign strategy, motion, social content, and editorial. Founder of Maison Mélange (luxury botanical body care, live on Shopify) and Silk Scheduling (appointment automation SaaS, Airtable CRM with Calendly API)."'::jsonb) on conflict(key) do nothing;
insert into public.portfolio_settings (key,value) values ('aboutExtra','"My approach is end-to-end — I design it and I build it. From Shopify stores to Netlify deployments, 3D sculpts in Nomad Sculpt to Sephora pitch decks, the work here spans conception through launch. Range with taste, not staying boxed into one lane."'::jsonb) on conflict(key) do nothing;
